	if (!check_id && entry)
		list_del(&entry->list);
	spin_unlock_bh(&msk->pm.lock);

	/* Note: entry might have been removed by another thread.
	 * We hold rcu_read_lock() to ensure it is not freed under us.
	 */
	if (stop_timer)
		sk_stop_timer_sync(sk, &entry->add_timer);

	rcu_read_unlock();
	return entry;
